def transform(grid):
    g=[row[:] for row in grid]
    # The nonzero runs in the template rows define the repeated sequences.
    seqs=[]
    for row in grid:
        run=[]
        for v in row+[0]:
            if v:
                run.append(v)
            elif run:
                if len(run)>1: seqs.append(run)
                run=[]
    mapping={}
    for seq in seqs:
        for i,v in enumerate(seq):
            mapping.setdefault(v,(seq,i))
    h,w=len(g),len(g[0])
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v and sum(x!=0 for x in row)==1:
                seq,i=mapping[v]
                start=c-i
                for j,x in enumerate(seq):
                    cc=start+j
                    if 0<=cc<w: g[r][cc]=x
    return g
